<?php
require dirname(__DIR__).'/lib.php';require dirname(__DIR__).'/imports.php';require dirname(__DIR__).'/campaigns.php';
function check($v,$m){if(!$v)throw new Exception($m);echo "OK $m\n";}
$d=seed(json_decode(file_get_contents(__DIR__.'/fixture.json'),true,512,JSON_THROW_ON_ERROR));camp_init($d);$cid='2026-2027';$gid='g1';$n=count($d['companies']);$d['companies']['other']=['name'=>'Taller Ejemplo','zone'=>'Alcalá','nif'=>'B12345678','emails'=>'other@example.org','kind'=>'Empresa','tutors'=>['t'=>['name'=>'Tutor']],'sites'=>[]];$existing=array_key_first($d['links'][$cid]);$old=$d['companies'][$existing];$data="\xEF\xBB\xBFEmpresa;NIF;Localidad;Correo;Tipo\nNueva Pyme;;Guía de Isora;nueva@example.org;Empresa\nNueva Pyme;;Guia de Isora;nueva@example.org;Empresa\nTaller Ejemplo;B12345678;Alcalá;other@example.org;Empresa\nOtro nombre;;Adeje;other@example.org;Empresa\nErrónea;;Alcalá;bad;Empresa\n";
$rows=imp_parse($data);$plan=imp_plan($d,$cid,$gid,$rows);check(array_column($plan,'action')===['create','skip','link','error','error'],'clasifica altas, duplicados, vínculos, colisiones y errores');check(count($d['companies'])===$n+1,'vista previa sin escritura');$before=$d['companies']['other'];$counts=imp_apply($d,$cid,$gid,$rows,$plan);check($counts===['create'=>1,'link'=>1,'skip'=>1,'error'=>2],'resultado del lote');check($d['companies']['other']===$before,'conserva ficha, tutores y centros');check($d['links'][$cid]['other']['confirmed']===0&&$d['links'][$cid]['other']['group']===$gid,'sin plazas confirmadas, grupo correcto');check(!$d['campaign_permissions'],'no autoriza campañas');check($d['companies'][$existing]===$old,'no cambia empresas previas');$plan2=imp_plan($d,$cid,$gid,$rows);check(!in_array('create',array_column($plan2,'action'))&&!in_array('link',array_column($plan2,'action')),'reimportación idempotente');$tsv=imp_parse("Razón social\tTeléfono\tLocalidad\nComercio X\t922123456\tAlcalá\n");check($tsv[0]['profile']['phone']==='922123456','pegar tabla TSV');$comma=imp_parse("Empresa,Localidad,Correo\n\"Empresa, S.L.\",Alcalá,x@example.org\n");check($comma[0]['profile']['name']==='Empresa, S.L.','CSV coma y comillas');$bad=imp_parse("Empresa;Correo\nA;x@example.org;extra\n");check(isset($bad[0]['error']),'columnas incorrectas');$cp=imp_parse(iconv('UTF-8','Windows-1252',"Empresa;Localidad\nPeña;Alcalá\n"));check($cp[0]['profile']['zone']==='Alcalá','codificación Windows-1252');
